(function(){
  const $=id=>document.getElementById(id),n=v=>Number(v||0).toLocaleString('pt-BR'),p=v=>`${Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}%`,cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;
  const download=(name,heads,rows)=>{const text='\uFEFF'+[heads.join(','),...rows.map(row=>row.map(cell).join(','))].join('\r\n'),a=Object.assign(document.createElement('a'),{href:URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),download:name});a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
  const option=(s,v,l)=>{const o=document.createElement('option');o.value=v;o.textContent=l;s.append(o)};
  function selected(d){const id=$('comparisonCandidate').value,office=$('comparisonOffice').value;return id==='__all__'?d.candidates.filter(c=>!office||c.office===office):d.candidates.filter(c=>c.id===id)}
  function sumCities(d,candidates){const cities=Object.fromEntries(d.municipalities.map(c=>[c.id,0]));for(const candidate of candidates)for(const [city,votes] of Object.entries(candidate.votes))cities[city]+=Number(votes);return cities}
  function matrix(d){const office=$('comparisonOffice').value,candidates=d.candidates.filter(c=>!office||c.office===office),rows=candidates.map(c=>({name:c.name,office:c.office,votes:c.votes,total:c.total_votes}));if(!office){const votes=sumCities(d,candidates);rows.unshift({name:'Total UP · todos os cargos',office:'Todos os cargos',votes,total:Object.values(votes).reduce((a,v)=>a+v,0),totalRow:true})}return rows}
  function renderMatrix(d){const cities=d.municipalities,rows=matrix(d),table=$('candidateMatrix');table.tHead.innerHTML=`<tr><th>Candidatura</th><th>Cargo</th><th>Total Baixada</th>${cities.map(c=>`<th>${c.name}</th>`).join('')}</tr>`;table.tBodies[0].innerHTML=rows.map(r=>`<tr${r.totalRow?' class="aggregate-row"':''}><td>${r.name}</td><td>${r.office}</td><td>${n(r.total)}</td>${cities.map(c=>`<td>${n(r.votes[c.id])}</td>`).join('')}</tr>`).join('')}
  function indicators(d){const candidates=selected(d),aggregate=candidates.length!==1;return d.municipalities.map(city=>{let votes=0,valid=0;for(const c of candidates){votes+=Number(c.votes[city.id]||0);valid=Number(c.valid_votes[city.id]||0)}return {candidate:aggregate?'Total UP · todos os cargos':candidates[0].name,office:aggregate?'Todos os cargos':candidates[0].office,city:city.name,votes,electorate:city.electorate,electorateShare:city.electorate?100*votes/city.electorate:0,validShare:aggregate?null:(valid?100*votes/valid:0)}}).sort((a,b)=>b.votes-a.votes)}
  function renderIndicators(d){$('comparisonRows').querySelector('tbody').innerHTML=indicators(d).map(r=>`<tr><td>${r.candidate}</td><td>${r.office}</td><td>${r.city}</td><td>${n(r.votes)}</td><td>${n(r.electorate)}</td><td>${p(r.electorateShare)}</td><td>${r.validShare===null?'—':p(r.validShare)}</td></tr>`).join('')}
  function neighborhoods(d){const ids=new Set(selected(d).map(c=>c.id)),municipality=$('comparisonMunicipality').value,sums=new Map();for(const r of d.neighborhoods){if(!ids.has(r.candidate_id)||(municipality&&r.municipality_id!==municipality))continue;const key=`${r.municipality_id}:${r.neighborhood}`;if(!sums.has(key))sums.set(key,{...r,votes:0});sums.get(key).votes+=Number(r.votes)}return [...sums.values()].map(r=>({...r,share:r.electorate?100*r.votes/r.electorate:0})).sort((a,b)=>b.votes-a.votes||a.neighborhood.localeCompare(b.neighborhood,'pt-BR'))}
  function renderNeighborhoods(d){const rows=neighborhoods(d);$('comparisonNeighborhoods').querySelector('tbody').innerHTML=rows.map(r=>`<tr><td>${r.neighborhood}</td><td>${r.municipality}</td><td>${n(r.votes)}</td><td>${n(r.electorate)}</td><td>${p(r.share)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum bairro neste filtro.</td></tr>'}
  function render(d){renderMatrix(d);renderIndicators(d);renderNeighborhoods(d)}
  fetch('data/comparative-tables.json').then(r=>r.json()).then(d=>{const offices=[...new Set(d.candidates.map(c=>c.office))].sort();option($('comparisonOffice'),'','Todos os cargos');offices.forEach(v=>option($('comparisonOffice'),v,v));option($('comparisonCandidate'),'__all__','Todas as candidaturas da UP');d.candidates.slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).forEach(c=>option($('comparisonCandidate'),c.id,`${c.name} · ${c.office}`));option($('comparisonMunicipality'),'','Todos os municípios');d.municipalities.forEach(c=>option($('comparisonMunicipality'),c.id,c.name));$('comparisonOffice').onchange=()=>{$('comparisonCandidate').value='__all__';render(d)};$('comparisonCandidate').onchange=() => render(d);$('comparisonMunicipality').onchange=()=>render(d);$('downloadCandidateMatrix').onclick=()=>{const cities=d.municipalities;download('up-baixada-matriz-candidaturas.csv',['candidatura','cargo','total_baixada',...cities.map(c=>c.name)],matrix(d).map(r=>[r.name,r.office,r.total,...cities.map(c=>r.votes[c.id])]))};$('downloadComparisonRows').onclick=()=>download('up-baixada-indicadores-municipais.csv',['candidatura','cargo','municipio','votos','eleitorado','percentual_eleitorado','percentual_validos_cargo'],indicators(d).map(r=>[r.candidate,r.office,r.city,r.votes,r.electorate,r.electorateShare,r.validShare??'']));$('downloadNeighborhoodRows').onclick=()=>download('up-baixada-bairros.csv',['bairro','municipio','votos','eleitorado_nas_secoes','percentual_eleitorado'],neighborhoods(d).map(r=>[r.neighborhood,r.municipality,r.votes,r.electorate,r.share]));render(d)}).catch(()=>{$('candidateMatrix').querySelector('tbody').innerHTML='<tr><td colspan="12">Não foi possível carregar as tabelas comparativas.</td></tr>'});
})();
